def compute_motor_command(self, m_ag):
        """ Compute the motor command by restricting it to the bounds. """
        m_ag_clipped = np.clip(m_ag, self.min_m_ag, self.max_m_ag)
        m_ag_diff = m_ag_clipped - m_ag
        m_ag_clipped_diff_norm = np.linalg.norm(m_ag_diff)

        if m_ag_clipped_diff_norm < self.m_ag_clipped_eps:
            m_ag_command = m_ag_clipped
        else:
            m_ag_command = m_ag_clipped - m_ag_diff * self.m_ag_clipped_eps / m_ag_clipped_diff_norm

        return m_ag_command

