    if end <= start:
        return
    if start == end:
        yield start
        return
    if start < end:
        yield start
        start += 1
    for line in reader:
        if line.startswith(start):
            if line.startswith(end):
                return
            yield line
        elif line.startswith(end):
            return
        elif line.startswith(start):
