def _md5_compare(self, file_path, checksum, block_size=2 ** 13):
        """Compare a given MD5 checksum with one calculated from a file."""
        with open(file_path, "rb") as fp:
            md5 = hashlib.md5()
            while True:
                data = fp.read(block_size)
                if not data:
                    break
                md5.update(data)
            return md5.hexdigest() == checksum

